import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# --------------------------------------------------------------------------------
# Custom CUDA ReLU operator
# --------------------------------------------------------------------------------
relu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void relu_kernel(const float* __restrict__ x, float* __restrict__ y, int size) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < size) {
        y[i] = x[i] > 0 ? x[i] : 0.0f;
    }
}

torch::Tensor relu_forward(torch::Tensor x) {
    auto y = torch::zeros_like(x);
    int size = x.numel();
    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    relu_kernel<<<blocks, threads>>>(x.data_ptr<float>(), y.data_ptr<float>(), size);
    return y;
}
""".strip()

relu_cpp_source = "torch::Tensor relu_forward(torch::Tensor x);"

custom_relu = load_inline(
    name="custom_relu",
    cpp_sources=relu_cpp_source,
    cuda_sources=relu_source,
    functions=["relu_forward"],
    verbose=False,
    extra_cflags=[],
    extra_ldflags=[],
)


# A simple wrapper module for the custom ReLU
class CustomReLU(nn.Module):
    def __init__(self, inplace=False):
        super(CustomReLU, self).__init__()
        self.inplace = inplace

    def forward(self, x):
        # This extension doesn't currently do "in-place" in the strict sense,
        # but we mirror the API usage
        return custom_relu.relu_forward(x)


# --------------------------------------------------------------------------------
# Model Definition with CustomReLU
# --------------------------------------------------------------------------------
class DenseBlockNew(nn.Module):
    def __init__(self, num_layers: int, num_input_features: int, growth_rate: int):
        super(DenseBlockNew, self).__init__()
        layers = []
        for i in range(num_layers):
            layers.append(self._make_layer(num_input_features + i * growth_rate, growth_rate))
        self.layers = nn.ModuleList(layers)

    def _make_layer(self, in_features: int, growth_rate: int):
        return nn.Sequential(
            nn.BatchNorm2d(in_features),
            CustomReLU(inplace=True),  # Replaced nn.ReLU with CustomReLU
            nn.Conv2d(in_features, growth_rate, kernel_size=3, padding=1, bias=False),
            nn.Dropout(0.0)
        )

    def forward(self, x):
        features = [x]
        for layer in self.layers:
            new_feature = layer(x)
            features.append(new_feature)
            x = torch.cat(features, 1)
        return x


class TransitionLayerNew(nn.Module):
    def __init__(self, num_input_features: int, num_output_features: int):
        super(TransitionLayerNew, self).__init__()
        self.transition = nn.Sequential(
            nn.BatchNorm2d(num_input_features),
            CustomReLU(inplace=True),  # Replaced nn.ReLU with CustomReLU
            nn.Conv2d(num_input_features, num_output_features, kernel_size=1, bias=False),
            nn.AvgPool2d(kernel_size=2, stride=2)
        )

    def forward(self, x):
        return self.transition(x)


class ModelNew(nn.Module):
    def __init__(self, growth_rate: int = 32, num_classes: int = 1000):
        super(ModelNew, self).__init__()

        # Initial convolution and pooling
        self.features = nn.Sequential(
            nn.Conv2d(3, 64, kernel_size=7, stride=2, padding=3, bias=False),
            nn.BatchNorm2d(64),
            CustomReLU(inplace=True),  # Replaced nn.ReLU with CustomReLU
            nn.MaxPool2d(kernel_size=3, stride=2, padding=1)
        )

        num_features = 64
        block_layers = [6, 12, 24, 16]  # DenseNet121 configuration

        self.dense_blocks = nn.ModuleList()
        self.transition_layers = nn.ModuleList()

        for i, num_layers in enumerate(block_layers):
            block = DenseBlockNew(num_layers=num_layers, num_input_features=num_features, growth_rate=growth_rate)
            self.dense_blocks.append(block)
            num_features = num_features + num_layers * growth_rate

            if i != len(block_layers) - 1:
                transition = TransitionLayerNew(
                    num_input_features=num_features,
                    num_output_features=num_features // 2
                )
                self.transition_layers.append(transition)
                num_features = num_features // 2

        self.final_bn = nn.BatchNorm2d(num_features)
        self.classifier = nn.Linear(num_features, num_classes)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self.features(x)
        for i, block in enumerate(self.dense_blocks):
            x = block(x)
            if i != len(self.dense_blocks) - 1:
                x = self.transition_layers[i](x)
        x = self.final_bn(x)
        x = custom_relu.relu_forward(x)  # Final ReLU replaced with custom kernel
        x = F.adaptive_avg_pool2d(x, (1, 1)).view(x.size(0), -1)
        x = self.classifier(x)
        return x


